INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 51, 'theory', 'Quiz: code quality and patterns');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 0, 'Why does a project need an automatic formatter (black, ruff format)?', '["To make the program faster", "So that arguments about style disappear: the code is formatted the same way for the whole team", "To check types", "To delete comments"]', 1, 'The formatter and the linter are connected to pre-commit hooks and to CI.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 1, 'What does 100% test coverage mean?', '["There are no bugs in the code", "All lines were executed during the tests, but this does not prove correctness", "All functions are annotated", "The tests run fast"]', 1, 'Without checks (assert), coverage is useless: aim for scenarios and edge cases.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 2, 'What is the simplest way to implement the Strategy pattern in Python?', '["Only through classes and inheritance", "A special library is needed", "It is impossible", "Pass a function as a parameter"]', 3, 'Functions are first-class values, so a strategy comes down to a function parameter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 3, 'What does the single responsibility principle say?', '["A function or class should have one reason to change", "A project should have one class", "All functions should be shorter than a line", "Exceptions are forbidden"]', 0, 'If a function reads, computes and writes, it has three reasons to change.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 51, 4, 'Where should you start refactoring?', '["By rewriting everything from scratch", "By renaming all the files", "With tests that pin down the current behavior", "By turning off the linter"]', 2, 'Then come small steps, with checks after each one.');
